using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Employees;
using PeopleHub.Domain.Entities;
using System.Text;
namespace PeopleHub.Tests;
public class EmployeeImportValidationTests
{
 class User(bool allowed=true):ICurrentUser{public string Email=>"validation@example.local";public int? EmployeeId=>null;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>allowed&&p==Perm.EmpManage;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.EnsureCreatedAsync();d.Add(new Branch{Id=1,Name="Fictional"});d.Add(new Department{Id=1,Name="Fictional"});d.Add(new JobTitle{Id=1,Name="Fictional"});d.Add(new Employee{Code="EXIST",FullName="Fictional existing",Email="existing@example.local",BranchId=1,DepartmentId=1,JobTitleId=1});await d.SaveAsync();return d;}
 static byte[] Csv(string row)=>Encoding.UTF8.GetBytes(EmployeeImportValidation.Header+"\r\n"+row);
 static EmployeeImportValidation S(AppDbContext d,bool allowed=true)=>new(d,new User(allowed));
 const string Valid="FIC-NEW,Fictional employee,موظف تجريبي,new@example.local,2027-01-01,1,1,1";
 [Fact]public async Task ValidPreviewDoesNotWriteAnyEmployeeAuditOrAccount(){await using var d=await Db();var result=await S(d).PreviewAsync(Csv(Valid));Assert.Equal(1,result.ValidRows);Assert.Equal(2,Assert.Single(result.Rows).Row);Assert.Equal(1,await d.Set<Employee>().CountAsync());Assert.Empty(await d.Set<AuditLog>().ToListAsync());Assert.Empty(await d.Set<AppUser>().ToListAsync());Assert.False(d.ChangeTracker.HasChanges());}
 [Fact]public async Task DuplicatesInSourceAndExistingAreReportedOnEveryAffectedRow(){await using var d=await Db();var row=" exist ,Fictional,, EXISTING@example.local ,2027-01-01,1,1,1";var v=await S(d).PreviewAsync(Csv(row+"\n"+row.ToUpperInvariant()));Assert.Equal(0,v.ValidRows);Assert.All(v.Rows,x=>{Assert.Contains("existingCode",x.Errors);Assert.Contains("existingEmail",x.Errors);Assert.Contains("duplicateCode",x.Errors);Assert.Contains("duplicateEmail",x.Errors);});}
 [Fact]public async Task QuotedCommasEscapedQuotesAndUtf8BomAreSupported(){await using var d=await Db();var bytes=Encoding.UTF8.GetPreamble().Concat(Csv("FIC,\"Fictional, \"\"quoted\"\" name\",اسم,new@example.local,2027-01-01,1,1,1")).ToArray();var v=await S(d).PreviewAsync(bytes);Assert.Equal(1,v.ValidRows);Assert.Equal("Fictional, \"quoted\" name",Assert.Single(v.Rows).Name);}
 [Theory][InlineData("FIC,,اسم,bad,2027-02-30,999,999,999")][InlineData("FIC,Name,,bad,not-date,-1,0,unknown")]
 public async Task RequiredFormatsAndReferencesAreReported(string row){await using var d=await Db();var v=await S(d).PreviewAsync(Csv(row));Assert.Equal(0,v.ValidRows);var e=Assert.Single(v.Rows).Errors;foreach(var key in new[]{"email","hireDate","department","branch","jobTitle"})Assert.Contains(key,e);}
 [Fact]public async Task MalformedQuotesHeadersAndExtraColumnsAreRejected(){await using var d=await Db();foreach(var text in new[]{"Wrong\nvalue",EmployeeImportValidation.Header+",Salary\n"+Valid+",5000",EmployeeImportValidation.Header+"\n\"unclosed",EmployeeImportValidation.Header+"\n\"x\"tail,,,,,,,",EmployeeImportValidation.Header})await Assert.ThrowsAsync<DomainException>(()=>S(d).PreviewAsync(Encoding.UTF8.GetBytes(text)));}
 [Fact]public async Task ShortRowAndMultilineValueAreInvalidNotSilentlyDropped(){await using var d=await Db();var v=await S(d).PreviewAsync(Csv("short,row\nFIC,\"Fictional\nmultiline\",,new@example.local,2027-01-01,1,1,1"));Assert.Equal(2,v.Rows.Count);Assert.Equal(0,v.ValidRows);Assert.Contains("columns",v.Rows[0].Errors);Assert.Contains("controls",v.Rows[1].Errors);}
 [Fact]public async Task FileSizeRowLimitEncodingAndPermissionAreBounded(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>S(d,false).PreviewAsync(Csv(Valid)));await Assert.ThrowsAsync<DomainException>(()=>S(d).PreviewAsync(new byte[EmployeeImportValidation.MaxBytes+1]));await Assert.ThrowsAsync<DomainException>(()=>S(d).PreviewAsync([]));await Assert.ThrowsAsync<DomainException>(()=>S(d).PreviewAsync([255,254,255]));await Assert.ThrowsAsync<DomainException>(()=>S(d).PreviewAsync(Csv(string.Join('\n',Enumerable.Repeat(Valid,201)))));Assert.Equal(200,(await S(d).PreviewAsync(Csv(string.Join('\n',Enumerable.Repeat(Valid,200))))).Rows.Count);}
 [Fact]public async Task PreviewRechecksCurrentReferencesAndDoesNotRetainDetachedResult(){await using var d=await Db();var v=await S(d).PreviewAsync(Csv(Valid));v.Rows[0].Errors.Add("Local edit");Assert.Equal(1,(await S(d).PreviewAsync(Csv(Valid))).ValidRows);d.Add(new Employee{Code="FIC-NEW",FullName="Fictional now existing",Email="new@example.local",BranchId=1,DepartmentId=1,JobTitleId=1});await d.SaveAsync();Assert.Equal(0,(await S(d).PreviewAsync(Csv(Valid))).ValidRows);}

 [Fact]public void UploadControllerRequiresEmployeeManagementAndKeepsBoundedFileBufferInMemory(){var type=typeof(PeopleHub.Web.Controllers.ImportValidationController);var permission=Assert.Single(type.GetCustomAttributes(typeof(PeopleHub.Web.Services.RequirePermAttribute),true).Cast<PeopleHub.Web.Services.RequirePermAttribute>());Assert.NotNull(permission);var limits=Assert.Single(type.GetMethod("Preview")!.GetCustomAttributes(typeof(Microsoft.AspNetCore.Mvc.RequestFormLimitsAttribute),true).Cast<Microsoft.AspNetCore.Mvc.RequestFormLimitsAttribute>());Assert.True(limits.MemoryBufferThreshold>=EmployeeImportValidation.MaxBytes);Assert.Equal(300000,limits.MultipartBodyLengthLimit);}
}
